import React, { useEffect, useMemo, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import HelpTip from '../components/HelpTip.jsx';
import { joinDealAuthenticated, postDealMessage, submitDealEvidence } from '../lib/api';
import { buildDealMessageTypedData, buildDealEvidenceTypedData, signTypedData } from '../lib/eip712';
import { getErrorMessage } from '../lib/errorUtils';
import ErrorBanner from '../components/ErrorBanner.jsx';
import LoadingSpinner from '../components/LoadingSpinner.jsx';
import useArchiveTheme from '../hooks/useArchiveTheme.js';
import '../styles/admin-common.css';
import './DealJoinPage.css';

export default function DealJoinPage() {
  const { darkMode, toggleTheme } = useArchiveTheme();
  const location = useLocation();
  const token = useMemo(() => {
    const params = new URLSearchParams(location.search || '');
    return params.get('token') || '';
  }, [location.search]);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [deal, setDeal] = useState(null);
  const [message, setMessage] = useState('');
  const [evidenceDrafts, setEvidenceDrafts] = useState({});
  const [wallet, setWallet] = useState({ address: '', chainId: '', connecting: false });
  const [requireSignature, setRequireSignature] = useState(true);
  const [successMsg, setSuccessMsg] = useState('');

  function hasEthereum() {
    return typeof window !== 'undefined' && !!window.ethereum?.request;
  }

  async function connectWallet() {
    setError('');
    if (!hasEthereum()) {
      setError('No wallet detected. Install MetaMask or use a wallet-enabled browser.');
      return;
    }
    setWallet((w) => ({ ...w, connecting: true }));
    try {
      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
      const address = Array.isArray(accounts) ? String(accounts[0] || '') : '';
      const chainId = await window.ethereum.request({ method: 'eth_chainId' });
      setWallet({ address, chainId: String(chainId || ''), connecting: false });
    } catch (e) {
      setWallet((w) => ({ ...w, connecting: false }));
      setError(e?.message || 'Failed to connect wallet');
    }
  }

  function parseChainId(cid) {
    if (cid == null || cid === '') return 8453;
    const n = typeof cid === 'string' && cid.startsWith('0x') ? parseInt(cid, 16) : Number(cid);
    return Number.isFinite(n) ? n : 8453;
  }

  useEffect(() => {
    if (!token) {
      setLoading(false);
      setError('Missing join token.');
      return;
    }
    setLoading(true);
    setError('');
    joinDealAuthenticated(token)
      .then((data) => {
        if (!data?.ok || !data?.item) throw new Error(data?.error || 'Failed to join deal');
        setDeal(data.item);
      })
      .catch((e) => setError(getErrorMessage(e, 'Failed to join deal')))
      .finally(() => setLoading(false));
  }, [token]);

  async function sendMessage() {
    const text = message.trim();
    if (!text || !deal?._id) return;
    setError('');
    try {
      let signature = '';
      let authorWallet = '';
      let typedData = null;
      if (wallet.address && requireSignature) {
        const ts = new Date().toISOString();
        typedData = buildDealMessageTypedData(parseChainId(wallet.chainId), deal._id, text, ts);
        signature = await signTypedData(typedData, wallet.address);
        authorWallet = wallet.address;
      }
      const data = await postDealMessage(deal._id, { text, authorWallet, signature, typedData });
      if (!data?.ok || !data?.item) throw new Error(data?.error || 'Failed to send message');
      setDeal(data.item);
      setMessage('');
      setSuccessMsg('Message sent.');
      setTimeout(() => setSuccessMsg(''), 2500);
    } catch (e) {
      setError(getErrorMessage(e, 'Failed to send message'));
    }
  }

  async function submitEvidence(milestoneId) {
    if (!deal?._id || !milestoneId) return;
    const evidenceValue = String(evidenceDrafts[milestoneId] || '').trim();
    if (!evidenceValue) return;
    setError('');
    try {
      let signature = '';
      let authorWallet = '';
      let typedData = null;
      if (wallet.address && requireSignature) {
        const ts = new Date().toISOString();
        typedData = buildDealEvidenceTypedData(parseChainId(wallet.chainId), deal._id, milestoneId, evidenceValue, ts);
        signature = await signTypedData(typedData, wallet.address);
        authorWallet = wallet.address;
      }
      const data = await submitDealEvidence(deal._id, milestoneId, { evidenceValue, authorWallet, signature, typedData });
      if (!data?.ok || !data?.item) throw new Error(data?.error || 'Failed to submit evidence');
      setDeal(data.item);
      setEvidenceDrafts((prev) => ({ ...prev, [milestoneId]: '' }));
      setSuccessMsg('Evidence submitted.');
      setTimeout(() => setSuccessMsg(''), 2500);
    } catch (e) {
      setError(getErrorMessage(e, 'Failed to submit evidence'));
    }
  }

  function retryLoad() {
    if (!token) {
      setError('Missing join token.');
      return;
    }
    setLoading(true);
    setError('');
    joinDealAuthenticated(token)
      .then((data) => {
        if (!data?.ok || !data?.item) throw new Error(data?.error || 'Failed to join deal');
        setDeal(data.item);
      })
      .catch((e) => setError(getErrorMessage(e, 'Failed to join deal')))
      .finally(() => setLoading(false));
  }

  return (
    <div className={`dealJoin admin-page authenticated ${darkMode ? 'dark-theme' : 'light-theme'}`}>
      <header className="admin-header dealJoinHeader">
        <div>
          <h1>🤝 Deal join</h1>
          <p className="muted">
            You’re viewing this deal as the counterparty. Add messages and submit milestone evidence below.
            <HelpTip
              title="Privacy note"
              body="This link acts like a key. Don’t post it publicly."
              example="Send privately to the counterparty"
            />
          </p>
        </div>
        <div className="dealJoinActions">
          <Link to="/" className="btn ghost">
            Home
          </Link>
          <Link to="/deals" className="btn ghost">
            Deals
          </Link>
          <button className="btn ghost" onClick={toggleTheme} title="Toggle theme" aria-label="Toggle theme">
            {darkMode ? '☀️' : '🌙'}
          </button>
        </div>
      </header>

      <main className="dealJoinMain">
        {loading ? <LoadingSpinner label="Loading deal…" /> : null}
        {error ? <ErrorBanner message={error} onRetry={retryLoad} onDismiss={() => setError('')} /> : null}
        {successMsg ? (
          <div className="success" role="status" style={{ padding: '0.5rem 1rem', background: 'rgba(0,180,0,0.15)', borderRadius: 4 }}>
            {successMsg}
          </div>
        ) : null}

        {deal ? (
          <>
            <section className="card">
              <h3>
                Wallet (optional)
                <HelpTip
                  title="Wallet signatures"
                  body="If you connect a wallet, your messages/evidence can be signed for a stronger audit trail. This does not send any on-chain transactions."
                  example="Sign evidence: tracking number"
                />
              </h3>
              <div className="row rowWrap">
                <button className="btn primary" type="button" onClick={connectWallet} disabled={wallet.connecting}>
                  {wallet.address ? 'Wallet connected' : wallet.connecting ? 'Connecting…' : 'Connect wallet'}
                </button>
                {wallet.address ? <span className="muted small">Address: {wallet.address}</span> : null}
                {wallet.chainId ? <span className="muted small">Chain: {wallet.chainId}</span> : null}
                <label className="check" style={{ marginLeft: 'auto' }}>
                  <input type="checkbox" checked={requireSignature} onChange={(e) => setRequireSignature(e.target.checked)} />
                  <span className="muted small">Require signature</span>
                </label>
              </div>
            </section>

            <section className="card">
              <h2>{deal.title}</h2>
              {deal.description ? <div className="muted">{deal.description}</div> : null}
            </section>

            <section className="card">
              <h3>Milestones</h3>
              {(deal.milestones || []).length ? (
                <div className="milestones">
                  {deal.milestones.map((m) => (
                    <div key={m._id} className="milestone">
                      <div className="milestone-title">{m.title}</div>
                      <div className="muted small">evidence: {m.evidenceType || 'none'}</div>
                      {m.evidenceValue ? <div className="muted small">current: {m.evidenceValue}</div> : null}
                      {m.evidenceType && m.evidenceType !== 'none' ? (
                        <div className="row">
                          <input
                            value={evidenceDrafts[m._id] ?? ''}
                            onChange={(e) => setEvidenceDrafts((prev) => ({ ...prev, [m._id]: e.target.value }))}
                            placeholder="Evidence value"
                          />
                          <button className="btn ghost" type="button" onClick={() => submitEvidence(m._id)}>
                            Submit evidence
                          </button>
                        </div>
                      ) : null}
                    </div>
                  ))}
                </div>
              ) : (
                <div className="muted">No milestones.</div>
              )}
            </section>

            <section className="card">
              <h3>Messages</h3>
              <div className="messages">
                {(deal.messages || []).slice(-50).map((msg, idx) => (
                  <div key={msg._id || idx} className="message">
                    <div className="muted small">
                      {msg.author || 'system'} · {msg.createdAt ? new Date(msg.createdAt).toLocaleString() : ''}
                    </div>
                    <div className="message-text">{msg.text}</div>
                  </div>
                ))}
              </div>
              <div className="row">
                <input value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Write a message..." />
                <button className="btn primary" type="button" onClick={sendMessage}>
                  Send
                </button>
              </div>
            </section>
          </>
        ) : null}
      </main>
    </div>
  );
}

